import{_ as a,c as e,o as i,a2 as t}from"./chunks/framework.PGES7OoM.js";const g=JSON.parse('{"title":"register","description":"Register a new Curvy handle from an account signature.","frontmatter":{"editLink":false,"rawMarkdown":"# register\\n\\nRegister a new Curvy handle from an account signature.\\n\\nRuns the pre-registration checks, verifies the signature, derives the private\\nkeys, then registers and adds the account.\\n\\n## Import\\n\\n```ts\\nimport { register } from \\"@0xcurvy/curvy-sdk/actions\\";\\n```\\n\\n## Usage\\n\\n```ts\\nconst account = await register({ handle, signature });\\n```\\n\\n## Signature\\n\\n```ts\\nfunction register(parameters: RegisterParameters): Promise<CurvyAccount>\\n```\\n\\n## Returns\\n\\n`Promise<CurvyAccount>`\\n\\nThe action resolves or returns the value shown in the signature.\\n\\n## Parameters\\n\\n### `handle`\\n\\n- **Type:** `CurvyId`\\n- **Required:** yes\\n\\nThe Curvy handle to register.\\n\\n```ts\\nconst result = await register({\\n  handle, // [!code focus]\\n  signature,\\n});\\n```\\n\\n### `signature`\\n\\n- **Type:** `EvmSignatureData`\\n- **Required:** yes\\n\\nThe EVM registration signature and its signing address.\\n\\n```ts\\nconst result = await register({\\n  handle,\\n  signature, // [!code focus]\\n});\\n```\\n\\n### `config`\\n\\n- **Type:** `CurvyConfig`\\n- **Required:** no\\n\\nCurvy config to use. Defaults to the ambient config.\\n\\n```ts\\nconst result = await register({\\n  handle,\\n  signature,\\n  config, // [!code focus]\\n});\\n```\\n\\n## Errors\\n\\nErrors from config resolution and the underlying SDK operation are propagated to the caller.\\n\\n## Related\\n\\n- [Authentication guide](/for-programmers/authentication)\\n- [`registerWithPasskey`](/sdk/actions/auth/registerWithPasskey) — Register a new Curvy handle via a passkey PRF output.\\n- [`registerWithPrivateKeys`](/sdk/actions/auth/registerWithPrivateKeys) — Register a new Curvy handle from raw spending and viewing private keys.\\n\\n## Source\\n\\n[packages/@0xcurvy/sdk/src/actions/auth/register.ts](https://github.com/0xCurvy/curvy-monorepo/blob/main/packages/@0xcurvy/sdk/src/actions/auth/register.ts)\\n","rawMarkdownPath":"/_raw/sdk/actions/auth/register.md","rawMarkdownTitle":"register","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/actions/auth/register.md"},"headers":[],"params":{"sdkReferenceKind":"action","category":"auth","action":"register"},"relativePath":"sdk/actions/auth/register.md","filePath":"sdk/actions/[category]/[action].md","lastUpdated":1786448401000}'),n={name:"sdk/actions/auth/register.md"};function r(h,s,l,o,p,d){return i(),e("div",null,[...s[0]||(s[0]=[t("",31)])])}const k=a(n,[["render",r]]);export{g as __pageData,k as default};
